-- 119: the guides in Urdu, as DRAFTS (requested by the Owner, 2026-11-06).
--
-- Translated with the skill focolare-urdu-translation, to be reviewed by those who know Urdu well. Until then only
-- Admins see them (help_pages.draft, read by js/userguide.js). Generated by Documentazione/guide-help/build-ur.mjs.
-- Rows already there are left alone, so an edit made in the app stays. Safe to run again.
--
-- To open one reviewed guide to everyone:   update help_pages set draft = false where slug = 'boards_ur';
-- To open them all:                         update help_pages set draft = false where language = 'ur';

begin;

alter table public.help_pages add column if not exists draft boolean not null default false;

insert into public.help_pages (slug, guide_key, language, role, title, summary, section, audience, html_content, sort_order, draft, updated_at, updated_by_email)
values ('find-read_ur', 'find-read', 'ur', null, 'تلاش کریں اور پڑھیں', 'تلاش، فلٹر، سننا، ویڈیو، محفوظ کرنا', 'use', array['user'], $help_guide$<p class="lead">آرکائیو کی ہر دستاویز ایک ہی صفحے سے مل جاتی ہے۔ یوزر کے لیے اس کا نام <b>Library</b> ہے اور ٹیم کے لیے <b>Dashboard</b>۔</p>
<h2>دستاویز تلاش کریں</h2>
<ol>
<li><b>تلاش کے خانے میں لکھیں۔</b> یہ عنوانات، ٹیگز اور خود اردو متن میں تلاش کرتا ہے۔</li>
<li><b>یا نمبر لکھیں،</b> <b>ID #</b> میں، اگر آپ کو معلوم ہو۔</li>
<li><b>فہرست کو مختصر کریں،</b> <b>Filters</b> سے: Category, Author, Main topic, Recipient, Source, Collection, Language۔ کئی فلٹر ایک ساتھ کام کرتے ہیں۔</li>
<li><b>کسی سطر کو دبائیں</b> تاکہ دستاویز کھل جائے۔</li>
</ol>
<p>یوزر اور آپریٹر کے لیے <b>Language</b> شروع سے Urdu پر ہوتی ہے۔ اگر کچھ نہ ملے تو پہلے یہ فلٹر دیکھیں۔ <b>Clear all filters and search</b> سب کچھ نئے سرے سے شروع کرتا ہے۔</p>
<h2>دستاویز کے ساتھ آپ کیا کر سکتے ہیں</h2>
<ul>
<li><b>Open PDF</b>: فائل کھولتا ہے۔ جو PDF ابھی Drive پر نہیں پہنچی، اس کے لیے <b>Download</b> نظر آتا ہے۔</li>
<li><b>Read (large print)</b>: صرف متن، بڑے حروف میں۔</li>
<li><b>Open editable text</b>: متن دکھاتا ہے تاکہ آپ اسے کاپی کر سکیں۔ اس سے آرکائیو نہیں بدلتا۔</li>
<li><b>Listen</b> اور <b>Watch video</b>: تب نظر آتے ہیں جب دستاویز کی ریکارڈنگ یا ویڈیو موجود ہو۔</li>
<li><b>☆ Save</b>: اسے <b>My Space</b> میں رکھتا ہے، جو صرف آپ کے لیے ہے۔</li>
<li><b>Report a problem</b>: ٹیم کو بتاتا ہے، دستاویز کا نمبر پہلے سے لکھا ہوتا ہے۔</li>
</ul>
<details><summary>دوسری زبانیں اور نسخے</summary>
<p>ایک متن، اس کے ترجمے، آڈیو اور ویڈیو ایک ساتھ ہوتے ہیں۔ یہ آپ کو <b>Other versions of this document</b> کے نیچے ملتے ہیں: جسے کھولنا ہو اسے دبائیں۔ ستارہ اس نسخے کی نشانی ہے جو اس زبان اور اس صورت میں سب سے پہلے دکھایا جاتا ہے۔</p>
</details>
<details><summary>صرف آڈیو اور ویڈیو</summary>
<p><b>Audio and video only</b> کا بٹن صرف ریکارڈنگ اور ویڈیو دکھاتا ہے۔ جن سطروں میں ریکارڈنگ یا ویڈیو ہو ان پر بھی ایک نشان ہوتا ہے۔ یہ ان کے لیے مددگار ہے جو لکھ کر تلاش نہیں کر سکتے۔</p>
</details>
<details><summary>اس مہینے کا کلامِ حیات</summary>
<p><b>Start Here</b> میں پہلا بٹن اس مہینے کا کلامِ حیات کھولتا ہے، <b>Read</b> کے ساتھ، اور جب موجود ہوں تو <b>Listen</b> اور <b>Watch video</b> کے ساتھ۔ کلامِ حیات پر اس کے اپنے مہینے کی تاریخ ہوتی ہے، اس رسالے کی نہیں جس میں وہ چھپا۔</p>
</details>
<details><summary>مجھے دستاویز کیوں نہیں مل رہی؟</summary>
<ul>
<li>ہو سکتا ہے کوئی فلٹر ابھی لگا ہو، اکثر <b>Language</b>۔</li>
<li>جس دستاویز کی صرف PDF ہو وہ عنوان اور ٹیگز سے ملتی ہے، متن سے نہیں۔</li>
<li>کچھ دستاویزات مخصوص ہیں: جنہیں اجازت نہیں، ان کے لیے وہ بالکل نظر نہیں آتیں۔</li>
</ul>
</details>
<p><a class="btn" href="#" data-tab="dashboard">آرکائیو کھولیں</a></p>$help_guide$, 10, true, now(), 'migration 119')
on conflict (slug) do nothing;

insert into public.help_pages (slug, guide_key, language, role, title, summary, section, audience, html_content, sort_order, draft, updated_at, updated_by_email)
values ('boards_ur', 'boards', 'ur', null, 'بورڈز', 'اپنے گروپ میں پڑھیں اور لکھیں', 'use', array['user'], $help_guide$<p class="lead">بورڈ کسی گروپ کی مشترکہ جگہ ہے: غور و فکر، متن، لنک، تصویریں۔ <b>جو کچھ بورڈ پر لکھا جائے وہ آرکائیو میں شامل نہیں ہوتا۔</b> وہ نہ تلاش میں آتا ہے نہ رپورٹوں میں۔</p>
<h2>پڑھیں</h2>
<p><b>Boards</b> کھولیں اور اوپر کے بٹنوں سے گروپ چنیں۔ آپ ہر بورڈ پڑھ سکتے ہیں۔ ایپ خود نوٹ کر لیتی ہے کہ آپ نے پوسٹ دیکھ لی: کچھ دبانے کی ضرورت نہیں۔</p>
<h2>پوسٹ لکھیں</h2>
<ol>
<li>بورڈ چنیں اور <b>+ New post</b> دبائیں۔</li>
<li>پہلی بار قواعد پڑھیں اور <b>I understand, continue</b> دبائیں۔</li>
<li>اپنا متن لکھیں۔ آپ لنک یا تصویر بھی شامل کر سکتے ہیں۔</li>
<li>شائع کریں۔ اگر آپ یوزر ہیں تو پہلے اس بورڈ کا نگران اسے پڑھتا ہے۔ آپریٹر کی پوسٹ فوراً نظر آتی ہے۔</li>
</ol>
<details><summary>بورڈ کے قواعد</summary>
<ul>
<li>بورڈ اس گروپ کی تربیت اور روحانی زندگی کی خدمت کے لیے ہے۔</li>
<li>یہ اشتہار، سیاسی مہم، زنجیری پیغامات یا غیر متعلقہ باتوں کے لیے نہیں۔</li>
<li>نگران کوئی پوسٹ رد کر سکتا یا ہٹا سکتا ہے اور اسے وجہ بتانی ہوتی ہے۔</li>
<li>بار بار غلط استعمال سے آپریٹر کی ساکھ کم ہو سکتی ہے یا یوزر کو پوسٹ کرنے سے روکا جا سکتا ہے۔ نگران یہ تجویز کرتا ہے اور Formation یا HR کا سربراہ فیصلہ کرتا ہے: کبھی ایک شخص اکیلے نہیں۔</li>
</ul>
</details>
<details><summary>ایسی پوسٹ جو آرکائیو کے لائق ہو</summary>
<p>پوسٹ پر <b>Suggest for the archive</b> دبائیں۔ یہ تجویز بورڈ کے نگرانوں، Archive &amp; Data اور کوآرڈینیٹرز تک پہنچتی ہے، جو اسے معمول کے جائزے کے لیے پیش کر سکتے یا نامنظور کر سکتے ہیں۔</p>
</details>
<details><summary>پوسٹ کس نے پڑھی</summary>
<p>سب دیکھ سکتے ہیں کہ کتنے لوگوں نے پوسٹ پڑھی۔ کس نے پڑھی، یہ صرف بورڈ کے نگران، کوآرڈینیٹرز اور ایڈمن دیکھ سکتے ہیں۔</p>
</details>
<p><a class="btn" href="#" data-tab="boards">Boards کھولیں</a></p>$help_guide$, 20, true, now(), 'migration 119')
on conflict (slug) do nothing;

insert into public.help_pages (slug, guide_key, language, role, title, summary, section, audience, html_content, sort_order, draft, updated_at, updated_by_email)
values ('formation-paths_ur', 'formation-paths', 'ur', null, 'تربیتی راستے', 'داخلہ، کوئز، سرٹیفکیٹ', 'use', array['user'], $help_guide$<p class="lead">تربیتی راستہ ایک کورس ہے: ماڈیول اور ابواب جنہیں ترتیب سے پڑھنا ہوتا ہے، کوئز کے ساتھ اور آخر میں سرٹیفکیٹ۔</p>
<h2>راستے پر چلیں</h2>
<ol>
<li><b>Formation Paths</b> کھولیں اور <b>Catalog</b> دیکھیں۔</li>
<li>کوئی راستہ کھولیں۔ داخلے سے پہلے بھی آپ اس کا مواد پڑھ سکتے ہیں۔</li>
<li><b>Enroll</b> دبائیں۔ اس سے دوسرے شرکاء کے ساتھ <b>Discussion</b>، کوئز اور سرٹیفکیٹ کھل جاتے ہیں۔</li>
<li>ماڈیول کے آخر میں <b>Take quiz</b> دبائیں۔ نتیجہ فوراً نظر آتا ہے، اور <b>Retake</b> سے آپ دوبارہ کوشش کر سکتے ہیں۔</li>
<li>جب آپ راستے کی ضروریات پوری کر لیں تو سرٹیفکیٹ خود نظر آ جاتا ہے۔</li>
</ol>
<p>آپ کے سرٹیفکیٹ <b>My Profile → My Certificates</b> میں ہوتے ہیں۔ راستہ بند ہونے کے بعد بھی وہ وہیں رہتے ہیں۔</p>
<details><summary>راستہ چھوڑنا، اور آخری تاریخیں</summary>
<p><b>Withdraw</b> سے آپ کسی بھی وقت راستہ چھوڑ سکتے ہیں۔ راستے میں داخلے کی آخری تاریخ ہو سکتی ہے: اس کے بعد صفحے پر لکھا ہوتا ہے کہ داخلہ بند ہے۔</p>
</details>
<p><a class="btn" href="#" data-tab="formation">Formation Paths کھولیں</a></p>$help_guide$, 30, true, now(), 'migration 119')
on conflict (slug) do nothing;

insert into public.help_pages (slug, guide_key, language, role, title, summary, section, audience, html_content, sort_order, draft, updated_at, updated_by_email)
values ('propose_ur', 'propose', 'ur', null, 'مواد تجویز کریں', 'متن، PDF، آڈیو، ویڈیو: ایک ہی دروازہ', 'add', array['operator'], $help_guide$<p class="lead">Proposals آرکائیو میں مواد شامل کرنے کا واحد دروازہ ہے: آپ ایک فارم بھرتے ہیں، کوئی دوسرا اسے دیکھتا ہے، اور صرف اس کی منظوری سے متن شائع ہوتا ہے۔ کوئی اکیلا شائع نہیں کرتا۔</p>
<p>منظوری تک متن Library میں نظر نہیں آتا۔ تجویز کرنے سے بذاتِ خود کریڈٹ نہیں ملتے: اگر آپ معاوضہ چاہیں تو پہلے ٹیم سے طے کریں، وہ ایک ٹاسک بنائے گی۔</p>
<table><tr><th>آپ کیا کرنا چاہتے ہیں</th><th>کہاں سے شروع کریں</th></tr>
<tr><td>نیا متن شامل کرنا</td><td><b>Proposals → + New proposal</b>، یا Dashboard پر <b>+ Propose content</b></td></tr>
<tr><td>موجود متن کا ترجمہ یا دوسرا نسخہ شامل کرنا</td><td>متن کھولیں اور <b>+ Add a related version</b> دبائیں</td></tr>
<tr><td>مہینے کا کلامِ حیات تیار کرنا</td><td><b>Proposals → Word of Life</b></td></tr>
<tr><td>بورڈ کی پوسٹ کو آرکائیو میں لانا</td><td>پوسٹ پر <b>Propose for archive</b></td></tr></table>
<h2>مراحل</h2>
<ol>
<li><b>فارم کھولیں۔</b> <b>+ New proposal</b> دبائیں۔</li>
<li><b>دیکھیں کہ متن پہلے سے موجود تو نہیں۔</b> حصہ ۱ میں عنوان یا متن کے کسی جملے سے تلاش کریں۔ اگر یہی متن کسی دوسری زبان میں ملے تو <b>Link to this</b> دبائیں: خالی خانے خود بھر جاتے ہیں۔ اگر نہ ملے تو آگے بڑھیں: یہ نیا متن ہوگا۔</li>
<li><b>وہ معلومات بھریں جو سب نسخوں میں مشترک ہیں۔</b> حصہ ۲ میں <b>انگریزی عنوان، زمرہ، مصنف</b> اور <b>تاریخ یا مدت</b> ضروری ہیں۔ کلامِ حیات کے لیے اس کا اپنا مہینہ لکھیں، جیسے <code>2026-12</code>، رسالے کا نہیں۔ باقی اختیاری ہے۔</li>
<li><b>نسخہ بھریں۔</b> حصہ ۳ میں <b>زبان</b> اور <b>اس زبان میں عنوان</b> چنیں، پھر رسائی کا درجہ اور صورت۔</li>
<li><b>متن شامل کریں۔</b> اسے چسپاں کریں، یا <b>Or load the text from Word</b> استعمال کریں، اور <b>ہمیشہ اسے جانچیں</b>۔ متن ہی سے دستاویز تلاش میں ملتی ہے: اکیلی PDF صرف عنوان اور ٹیگز سے ملتی ہے۔</li>
<li><b>PDF شامل کریں، اگر ہو۔</b> متن یا PDF میں سے ایک کافی ہے، مگر دونوں بہتر ہیں۔</li>
<li><b>اور زبانیں؟</b> ہر ایک کے لیے <b>+ Another language</b> دبائیں۔ ایک فارم کے سب نسخے ایک ساتھ شائع ہوتے ہیں۔</li>
<li><b>بھیجیں۔</b> <b>Send for review</b> دبائیں۔ اگر کام پورا نہ ہو تو <b>Save draft</b> دبائیں اور بعد میں <b>My proposals</b> سے واپس آئیں۔</li>
</ol>
<div class="note"><b>رسائی کا درجہ:</b> تقریباً ہر چیز کے لیے <b>Public</b> اور <b>Private</b> ٹھیک ہیں۔ اگر یقین نہ ہو تو <b>Private</b> رہنے دیں، یعنی رجسٹرڈ یوزرز کو نظر آئے۔ <b>Reserved</b> صرف ایڈمن اور Formation کو نظر آتا ہے۔</div>
<details><summary>بھیجنے کے بعد: اشاعت تک</summary>
<p>فیصلہ کوئی ریوائزر یا کوآرڈینیٹر کرتا ہے، کبھی اپنی تجویز پر نہیں، اور اس کی منظوری سے فارم کے سب نسخے ایک ساتھ شائع ہو جاتے ہیں۔ <b>My proposals</b> ہمیشہ بتاتا ہے کہ آپ کی تجویز کہاں ہے۔</p>
<table><tr><th>حالت</th><th>مطلب</th><th>آپ کیا کر سکتے ہیں</th></tr>
<tr><td><b>Draft</b></td><td>صرف آپ کی</td><td><b>Edit</b> یا <b>Discard</b></td></tr>
<tr><td><b>Awaiting review</b></td><td>قطار میں، اتنے دن سے</td><td><b>Take back to edit</b>، جب تک کوئی اس پر کام نہ کر رہا ہو۔ ۳ دن بعد <b>Send a reminder</b>، پھر ہر ۳ دن بعد</td></tr>
<tr><td><b>To correct</b></td><td>جائزہ لینے والا تبدیلی چاہتا ہے: نوٹ وہیں لکھا ہے</td><td><b>Edit</b>، درست کریں، اور دوبارہ <b>Send for review</b></td></tr>
<tr><td><b>Published</b></td><td>آرکائیو میں ہے</td><td>کچھ نہیں</td></tr>
<tr><td><b>Rejected</b></td><td>قبول نہیں ہوئی: وجہ وہیں لکھی ہے</td><td>ضرورت ہو تو ٹیم سے بات کریں</td></tr></table>
<p>اشاعت پر دستاویز فوراً نظر آتی ہے اور PDF <b>Download</b> سے کھلتی ہے۔ پھر ایڈمن اسے Drive پر نقل کرتا ہے اور اس کے بعد وہ <b>Open PDF</b> سے کھلتی ہے۔ آپ کو کچھ نہیں کرنا۔</p>
</details>
<details><summary>متن، زبانوں اور نسخوں کو جوڑنا</summary>
<p>جڑے ہوئے متن کا مطلب ہے ایک ہی تخلیق: اصل، اس کے ترجمے، آڈیو اور ویڈیو۔ یہ فیصلہ ہمیشہ کوئی شخص کرتا ہے، سسٹم نہیں۔</p>
<ul>
<li><b>سب ایک ساتھ:</b> ایک ہی فارم میں، <b>+ Another language</b> سے۔</li>
<li><b>موجود متن، اسی سے شروع کر کے:</b> <b>+ Add a related version</b>۔ یہ سب سے محفوظ طریقہ ہے: فارم خود بھر جاتا ہے اور ربط ہٹایا نہیں جا سکتا۔</li>
<li><b>موجود متن، فارم سے شروع کر کے:</b> حصہ ۱ میں تلاش کریں اور <b>Link to this</b> دبائیں۔ یہاں <b>Remove the link</b> اسے ختم کر دیتا ہے۔</li>
<li><b>کلامِ حیات:</b> <b>Proposals → Word of Life</b> میں مہینہ چنیں۔ آپ کو اطالوی، انگریزی، اردو، ویڈیو اور آڈیو اپنی حالت کے ساتھ نظر آتے ہیں۔ کوئی ٹکڑا <b>+ Add</b> سے شامل کریں، یا سب ایک ساتھ <b>Propose everything missing together</b> سے۔</li>
</ul>
<p>صرف ایک ہی متن کے نسخوں کو جوڑیں۔ تفسیر، یا محض ملتا جلتا متن، الگ تخلیق ہے۔ اگر دو شائع شدہ دستاویزات ایک ہی متن ہوں تو کسی کوآرڈینیٹر سے انہیں جوڑنے کو کہیں۔</p>
<p>اسی زبان میں <b>نیا نسخہ</b>، جیسے نظرِ ثانی شدہ اردو، انہی راستوں سے آتا ہے۔ اشاعت پر اسے اس زبان اور صورت کا ستارہ مل جاتا ہے، اور پرانا نسخہ دیکھا جا سکتا ہے۔</p>
</details>
<details><summary>ترجمے</summary>
<p><b>بغیر معاوضے کے، تجویز کے ذریعے:</b></p>
<ol>
<li>اصل متن کھولیں۔</li>
<li>مدد چاہیے تو <b>Translate</b> اور پھر <b>Copy prompt + text</b> دبائیں، Claude میں چسپاں کریں، اور نتیجے کو مسودہ سمجھیں۔ اسے ہمیشہ کوئی ایسا شخص دوبارہ پڑھے جو اردو اچھی طرح جانتا ہو۔</li>
<li>جب تیار ہو جائے تو اصل پر <b>+ Add a related version</b> دبائیں۔</li>
<li>زبان جانچیں، اس زبان میں عنوان لکھیں، متن شامل کریں اور <b>Send for review</b> دبائیں۔</li>
</ol>
<p><b>معاوضے کے ساتھ، ٹاسک کے ذریعے:</b> کوآرڈینیٹر اصل پر ترجمے کا ٹاسک بناتا ہے، مترجم کی اہلیت والا اسے لیتا ہے، اور وہ <a href="#" data-help-guide="tasks">ٹاسک کے راستے</a> پر چلتا ہے۔</p>
<p>ایک ہی متن کے لیے دونوں راستے استعمال نہ کریں۔</p>
</details>
<details><summary>فائلوں کی صورتیں</summary>
<table><tr><th>کیا</th><th>قبول</th><th>حد</th><th>جاننے کی بات</th></tr>
<tr><td>متن</td><td>چسپاں، یا Word <code>.docx</code></td><td>Word ۲۰ MB تک</td><td>صرف متن رہتا ہے: ترتیب اور تصویریں نہیں۔ ٹیکسٹ باکس یا نوٹس رہ سکتے ہیں، اس لیے اصل سے ملا لیں</td></tr>
<tr><td>PDF</td><td><code>.pdf</code></td><td>۵۰ MB</td><td>اکیلی PDF متن کی تلاش میں نہیں ملتی</td></tr>
<tr><td>آڈیو</td><td>MP3, M4A, AAC, OGG, WEBM</td><td>۲۵ MB</td><td>MP3 اور M4A سب سے محفوظ ہیں۔ WAV قبول نہیں۔ <b>Read by</b> میں پڑھنے والے کا نام ضروری ہے</td></tr>
<tr><td>ویڈیو</td><td>YouTube یا Google Drive کا <code>https</code> لنک</td><td>فائل اپ لوڈ نہیں ہوتی</td><td>اصل Drive پر رکھیں</td></tr></table>
<p>پرانی Word <code>.doc</code>: پہلے اسے <code>.docx</code> میں محفوظ کریں۔ تصویریں: انہیں PDF میں رکھیں۔ InPage <code>.inp</code>: پہلے تبدیل کریں، جیسے نیچے بتایا گیا ہے۔</p>
</details>
<details><summary>InPage فائل کو تبدیل کرنا</summary>
<p>InPage کے اردو متن کو آرکائیو میں آنے سے پہلے Unicode بننا ضروری ہے۔ فائل آپ کے کمپیوٹر پر ہی رہتی ہے: تبدیلی براؤزر میں ہوتی ہے۔</p>
<ol>
<li><b>InPage Converter</b> کھولیں اور <code>.inp</code> فائل چنیں۔</li>
<li>چاہیں تو <b>Document ID</b> اور <b>English reference</b> بھریں: یہ Word فائل اور PDF کے اوپر نظر آتے ہیں۔</li>
<li><b>Convert</b> دبائیں۔ متن خانے میں آ جاتا ہے۔</li>
<li><b>اسے دوبارہ پڑھیں اور وہیں درست کریں۔</b> تبدیلی خودکار ہے، اس لیے غلطیاں ہو سکتی ہیں۔</li>
<li>سب سے آسان طریقہ: متن کاپی کر کے فارم کے <b>Text</b> میں چسپاں کریں۔ یا <b>Download Word (.docx)</b> دبا کر <b>Or load the text from Word</b> سے لوڈ کریں، یا <b>Generate PDF (print)</b> دبا کر <b>Save as PDF</b> چنیں۔</li>
</ol>
<p>Word اور PDF میں Jameel Noori Nastaleeq فونٹ استعمال ہوتا ہے: اسے کمپیوٹر پر انسٹال کریں۔ <b>Google Drive folder</b> کا خانہ اختیاری ہے: یہ فائلیں Drive پر ڈالتا ہے اور اسی نام کی فائلوں کی جگہ لے لیتا ہے۔</p>
</details>
<p><a class="btn" href="#" data-tab="proposals">Proposals کھولیں</a></p>$help_guide$, 40, true, now(), 'migration 119')
