insert into public.help_pages (slug, guide_key, language, role, title, summary, section, audience, html_content, sort_order, draft, updated_at, updated_by_email)
values ('read-aloud_ur', 'read-aloud', 'ur', null, 'متن بلند آواز سے پڑھیں', 'متن چنیں، ریکارڈ کریں، بھیجیں', 'add', array['operator', 'user'], $help_guide$<p class="lead">ہر رجسٹرڈ شخص کوئی متن بلند آواز سے پڑھ کر اپنے فون سے ریکارڈ کر سکتا ہے۔ اس طرح متن ان تک پہنچتے ہیں جنہیں پڑھنے میں مشکل ہوتی ہے یا جو پڑھ نہیں سکتے۔</p>
<p>ٹیم کا کوئی فرد ریکارڈنگ سنتا ہے۔ اگر وہ منظور کرے تو متن پر پڑھنے والے کے نام کے ساتھ <b>Listen</b> کا بٹن آ جاتا ہے۔ کسی امتحان کی ضرورت نہیں۔ ریکارڈنگ سے بذاتِ خود کریڈٹ نہیں ملتے: جو معاوضہ چاہے وہ پہلے ٹیم سے طے کرے، ٹیم ایک ٹاسک بنائے گی۔</p>
<h2>مراحل</h2>
<ol>
<li><b>متن چنیں۔</b> <b>Read aloud</b> کھولیں اور <b>Texts waiting for a voice</b> کے نیچے <b>Read this</b> دبائیں۔ یا کوئی متن کھول کر <b>Read aloud</b> دبائیں۔</li>
<li><b>رضامندی دیں، صرف پہلی بار۔</b> اس میں بتایا گیا ہے کہ کون سنے گا اور یہ کہ آپ کا نام دکھایا جائے گا۔ نام آپ کی پروفائل سے آتا ہے: اگر نہ ہو تو <b>My Profile</b> میں شامل کریں۔ پھر <b>I agree, continue</b> دبائیں۔</li>
<li><b>اب متن ۷ دن کے لیے آپ کا ہے۔</b> اگر آپ چلے جائیں تو یہ <b>Texts you are holding</b> میں ملے گا، واپس آنے کے لیے <b>Record</b> اور چھوڑنے کے لیے <b>Let it go</b> کے ساتھ۔ پہلی ریکارڈنگ کے لیے آپ ایک وقت میں ایک متن رکھ سکتے ہیں، بعد میں تین تک۔</li>
<li><b>۱۰ سیکنڈ آزمائیں۔</b> <b>Try now</b> دبائیں، فون پوچھے تو مائیکروفون کی اجازت دیں، اور ایک سطر پڑھیں۔ سن کر دیکھیں کہ آواز صاف ہے۔ یہ آزمائش محفوظ نہیں ہوتی۔</li>
<li><b>ریکارڈ کریں۔</b> <b>Start recording</b> دبائیں، متن اسکرین پر ہوگا۔ پیراگرافوں کے درمیان <b>Pause</b> اور <b>Continue</b> استعمال کریں، پھر <b>Finish</b>۔ اسکرین روشن رکھیں۔ ریکارڈنگ ۴۵ منٹ بعد خود رک جاتی ہے۔</li>
<li><b>دوبارہ سنیں۔</b> اگر ٹھیک ہو تو <b>Send to be heard</b> دبائیں۔ اگر نہیں تو <b>Record again</b> ریکارڈنگ مٹا کر نئے سرے سے شروع کرتا ہے۔</li>
<li><b>اپنی ریکارڈنگ پر نظر رکھیں۔</b> <b>My readings</b> میں یہ <b>Waiting to be heard</b> کے طور پر نظر آتی ہے۔ ۳ دن بعد آپ <b>Send a reminder</b> دبا سکتے ہیں، پھر ہر ۳ دن میں ایک بار۔</li>
</ol>
<details><summary>اگر آپ فون کا اپنا ریکارڈر پسند کریں</summary>
<p>مرحلہ ۵ پر <b>Or upload a recording made with your phone</b> استعمال کریں۔ MP3, M4A, AAC, OGG اور WEBM قبول ہیں، ۲۵ MB تک۔ MP3 اور M4A سب سے محفوظ ہیں۔ WAV قبول نہیں کیونکہ فائلیں بہت بڑی ہوتی ہیں۔</p>
</details>
<details><summary>اگر کوئی رکاوٹ آ جائے</summary>
<p>فون کال، دوسرا ٹیب یا بند صفحہ زیادہ سے زیادہ آخری چند سیکنڈ ضائع کرتا ہے۔ جب آپ اسی فون پر اسی متن پر واپس آئیں تو ایپ ملی ہوئی ریکارڈنگ پیش کرتی ہے، سننے اور بھیجنے کے لیے۔ کمزور کنکشن پر بھیجنا تین بار تک کوشش کرتا ہے، اور فائل پہنچنے تک فون پر رہتی ہے۔</p>
</details>
<details><summary>کون سے متن ریکارڈ ہو سکتے ہیں</summary>
<p>فہرست میں ۲۰ تک متن ہوتے ہیں، ہر ایک اپنی زبان اور اندازاً لمبائی کے ساتھ۔ متن ریکارڈ ہو سکتا ہے اگر:</p>
<ul>
<li>وہ لکھا ہوا متن ہو جو سب دیکھ سکیں، مخصوص نہ ہو؛</li>
<li>اسے دوبارہ پڑھا جا چکا ہو، یا وہ سٹیلا کے متون میں سے ہو؛</li>
<li>اسی زبان میں اس کی ریکارڈنگ ابھی نہ ہو؛</li>
<li>کوئی اسے رکھے ہوئے نہ ہو، نہ اس کا جائزہ چل رہا ہو؛</li>
<li>وہ آپ کی حد میں ہو: پہلی منظور شدہ ریکارڈنگ سے پہلے ۴۰۰۰ حروف، پھر ۲۰۰۰۰۔</li>
</ul>
<p>پہلے کلامِ حیات آتے ہیں، پھر باقی سب، اور ہر گروہ میں پہلے چھوٹے متن۔ آپ کسی بھی متن سے شروع کر سکتے ہیں: <b>Read aloud</b> کا بٹن تبھی نظر آتا ہے جب متن ریکارڈ ہو سکے۔</p>
</details>
<details><summary>سننے والا کیا فیصلہ کر سکتا ہے</summary>
<ul>
<li><b>OK, publish</b>، یا <b>OK, with a note</b>: فوراً شائع ہو جاتی ہے۔</li>
<li><b>Ask to record again</b>: آپ نوٹ دیکھتے ہیں اور دوبارہ ریکارڈ کرتے ہیں، کوئی نقصان نہیں۔ متن مزید ۷ دن آپ کا رہتا ہے۔</li>
<li><b>Not accepted</b>: آپ وجہ دیکھتے ہیں اور متن پھر آزاد ہو جاتا ہے۔</li>
</ul>
</details>
<details><summary>اگر آپ کا ارادہ بدل جائے</summary>
<p><b>Read aloud</b> کے نیچے <b>Withdraw my consent</b> آپ کی سب ریکارڈنگز فوراً ہٹا دیتا ہے۔ انتظار والی ختم ہو جاتی ہیں، رکھے ہوئے متن آزاد ہو جاتے ہیں اور فائلیں مٹا دی جاتی ہیں۔ جو خود نہ کر سکے وہ ایڈمن سے کہہ سکتا ہے۔</p>
<p>جو نقل کسی نے اپنے آلے پر محفوظ کر لی ہو وہ واپس نہیں آ سکتی۔ آرکائیو کا ریکارڈ اس عمل کا اندراج رکھتا ہے، آواز نہیں۔</p>
</details>
<p><a class="btn" href="#" data-tab="readings">Read aloud کھولیں</a></p>$help_guide$, 50, true, now(), 'migration 119')
