insert into public.help_pages (slug, guide_key, language, role, title, summary, section, audience, html_content, sort_order, draft, updated_at, updated_by_email)
values ('tasks_ur', 'tasks', 'ur', null, 'ٹاسک پر کام کریں', 'لینا، جمع کرانا، کریڈٹ، ساکھ', 'work', array['operator'], $help_guide$<p class="lead">ٹاسک طے شدہ کام ہے جس کی قدر کریڈٹ میں ہوتی ہے: آپ اسے لیتے ہیں، کرتے ہیں اور جمع کراتے ہیں، اور کریڈٹ تب ملتے ہیں جب کام جانچ کر منظور ہو جائے۔</p>
<p>اسے کوآرڈینیٹر یا ایڈمن بناتا ہے، اکثر کسی خاص دستاویز پر۔ بغیر معاوضے کے متن شامل کرنے کے لیے <a href="#" data-help-guide="propose">Proposals</a> استعمال کریں۔</p>
<h2>مراحل</h2>
<ol>
<li><b>ٹاسک تلاش کریں۔</b> <b>Tasks Store</b> کھلا کام زمرے، کریڈٹ اور عنوان کے ساتھ دکھاتا ہے۔ آپ <b>Category</b> اور <b>Min credits</b> سے فلٹر کر سکتے ہیں۔</li>
<li><b>اسے لیں۔</b> <b>Claim</b> دبائیں، <b>Your target due date</b> چنیں اور تصدیق کریں۔ تاریخ ایک وعدہ ہے: بعد میں بدلی نہیں جا سکتی، اس لیے حقیقت پسندانہ چنیں۔</li>
<li><b>اصل فائل ڈاؤن لوڈ کریں۔</b> <b>My Tasks → In progress</b> میں <b>Download original file</b> دبائیں۔ اگر نہ ہو تو ٹاسک بنانے والے کو بتائیں۔</li>
<li><b>کام کریں</b> اپنے کمپیوٹر پر، ٹاسک کی تفصیل کے مطابق۔</li>
<li><b>نتیجہ اپ لوڈ کریں۔</b> <b>Upload corrected file</b> دبائیں: <code>.inp</code>, <code>.doc</code>, <code>.docx</code> اور <code>.pdf</code> قبول ہیں۔ جمع کرانے تک آپ اسے بدل سکتے ہیں۔</li>
<li><b>جمع کرائیں۔</b> <b>Submit for review</b> دبائیں اور تصدیق کریں۔ اگر ٹاسک کسی دستاویز کا ہو تو بٹن اپ لوڈ کے بعد ہی کام کرتا ہے۔ اس کے بعد آپ کچھ نہیں بدل سکتے۔</li>
<li><b>انتظار کریں۔</b> ٹاسک <b>Waiting for review</b> میں چلا جاتا ہے۔</li>
<li><b>نتیجہ پڑھیں۔</b> <b>Closed</b> نتیجہ اور جائزہ لینے والے کا نوٹ دکھاتا ہے۔ کریڈٹ <b>My credits</b> میں اور اوپر کی پٹی میں نظر آتے ہیں۔</li>
</ol>
<details><summary>ٹاسک کی قسمیں، اور کون لے سکتا ہے</summary>
<table><tr><th>کام</th><th>ایپ میں زمرہ</th><th>کون لے سکتا ہے</th></tr>
<tr><td>ترجمہ</td><td>Italian to Urdu, English to Urdu</td><td>مترجم کی اہلیت</td></tr>
<tr><td>ٹائپنگ</td><td>Typing</td><td>کوئی بھی آپریٹر</td></tr>
<tr><td>پروف ریڈنگ</td><td>Proof Reading</td><td>کوئی بھی آپریٹر</td></tr>
<tr><td>نظرِ ثانی</td><td>Revision</td><td>ریوائزر کی اہلیت</td></tr>
<tr><td>دیگر</td><td>Content Creation, Others</td><td>کوئی بھی آپریٹر</td></tr></table>
<p>ٹاسک پر لکھی قدر ہی اصل ہے۔ <b>Revision</b> کے ٹاسک کو، جو متن پر کام ہے اور اس کے اپنے کریڈٹ ہیں، ریوائزر کے فیصلے سے نہ ملائیں، جو دوسروں کے ٹاسک جانچتا ہے اور اس کے کریڈٹ نہیں ہوتے۔</p>
</details>
<details><summary>جمع کرانے کے بعد: دو جانچ</summary>
<p><b>پہلی جانچ، ریوائزر۔</b> یہ ریوائزر یا کوآرڈینیٹر کرتا ہے، کبھی اپنے ٹاسک پر نہیں، اور اسے معلوم نہیں ہوتا کہ کام کس نے کیا۔</p>
<table><tr><th>فیصلہ</th><th>مطلب</th><th>کیا ہوتا ہے</th></tr>
<tr><td><b>OK</b></td><td>کام اچھا ہے</td><td>ایڈمن کے پاس جاتا ہے</td></tr>
<tr><td><b>OK, but...</b></td><td>اچھا ہے، کچھ ملاحظات کے ساتھ</td><td>ایڈمن کے پاس جاتا ہے، بند ہونے پر ساکھ میں تھوڑی کمی کے ساتھ</td></tr>
<tr><td><b>Fail</b></td><td>کافی اچھا نہیں</td><td>ٹاسک بند: کریڈٹ نہیں، ساکھ کم۔ ویسا ہی نیا ٹاسک آتا ہے، دوسروں کے لیے کھلا مگر آپ کے لیے نہیں</td></tr></table>
<p><b>دوسری جانچ، ایڈمن۔</b> انتظار میں ٹاسک <b>Approved</b> دکھاتا ہے۔ <b>Publish</b> اسے بند کرتا ہے: کریڈٹ شامل ہوتے ہیں اور ساکھ فیصلے کے مطابق بدلتی ہے۔ <b>Reject</b> مثبت فیصلے کے باوجود اسے وجہ کے ساتھ بند کرتا ہے: کریڈٹ نہیں اور Fail جیسی کمی۔</p>
<p>جب ٹاسک کسی دستاویز کا ہو تو ایڈمن پھر آخری PDF تیار کر کے نیا نسخہ شائع کرتا ہے۔ آپ کے کریڈٹ اس مرحلے پر منحصر نہیں۔</p>
</details>
<details><summary>کریڈٹ</summary>
<p>ٹاسک کے کریڈٹ اس کی شرح ضرب صفحات ہیں، جمع کوئی اضافی، اور صرف ایک بار شامل ہوتے ہیں، جب ایڈمن <b>Publish</b> دبائے۔ کوآرڈینیٹر مشکل یا جلدی کی وجہ سے، سبب بتا کر، اضافی کریڈٹ دے سکتا ہے؛ ایک خاص حد سے اوپر Coordination کے سربراہ کی منظوری ضروری ہے۔</p>
<p><b>My Tasks → My credits</b> میں <b>Earned</b>، <b>In progress</b> (ابھی شامل نہیں) اور <b>Redeemed</b> (Publish سے بند ٹاسک، جس کا مطلب ادائیگی نہیں) نظر آتے ہیں۔</p>
<p>اس پہلے مرحلے میں کام رضاکارانہ ہے اور کریڈٹ پیسوں میں نہیں بدلتے۔ بعد میں ایک کریڈٹ کی قدر ہوگی، سب کے لیے برابر، جمع شدہ فنڈز کے مطابق۔ شرحیں اور ادائیگیاں ابھی طے ہونی ہیں۔</p>
</details>
<details><summary>ساکھ</summary>
<p>۰ سے ۱۰۰ تک کا نمبر جو ۵۰ سے شروع ہوتا ہے اور بتاتا ہے کہ آپ کا کام کتنا قابلِ اعتماد ہے۔ یہ اوپر کی پٹی میں نظر آتا ہے۔ یہ صرف درج شدہ واقعات سے بدلتا ہے، اور بڑا ٹاسک چھوٹے سے زیادہ اثر رکھتا ہے۔ قدریں ابھی طے ہونی ہیں۔</p>
<ul>
<li><b>OK:</b> بڑھتی ہے۔ <b>OK, but...:</b> تھوڑی کم ہوتی ہے۔ <b>Fail</b> یا <b>Reject:</b> زیادہ کم ہوتی ہے۔</li>
<li><b>Give up this task</b>، یا کوآرڈینیٹر کا اسے کسی اور کو دینا: کوئی تبدیلی نہیں۔</li>
<li>کوآرڈینیٹر کا اسے <b>Free up</b> سے واپس لینا، یا بورڈ کا غلط استعمال: کم ہوتی ہے۔</li>
</ul>
<p>کوئی حد خود نہیں لگتی: ساکھ آپ کو ٹاسک لینے سے نہیں روکتی۔ اگر بہت کم ہو جائے تو HR اور کوآرڈینیٹرز دیکھ لیتے ہیں۔ مقصد آپ سے بات کرنا ہے، سزا دینا نہیں۔</p>
</details>
<details><summary>اگر کچھ غلط ہو جائے</summary>
<ul>
<li><b>آپ مکمل نہیں کر سکتے:</b> <b>Give up this task</b> دبائیں اور وجہ لکھیں۔ ٹاسک پھر آزاد ہو جاتا ہے، کوئی نقصان نہیں۔ یہ صرف جمع کرانے سے پہلے ہو سکتا ہے۔</li>
<li><b>آپ کو دیر ہو گئی:</b> ٹاسک <b>Overdue</b> دکھاتا ہے۔ خودکار کمی نہیں ہوتی اور تاریخ نہیں بدلتی: ٹیم کو بتائیں۔ اگر جواب نہ دیں تو کوآرڈینیٹر <b>Free up</b> سے اسے واپس لے سکتا ہے، اور آپ کی ساکھ کم ہوتی ہے۔</li>
<li><b>غلط فائل اپ لوڈ ہو گئی:</b> جمع کرانے سے پہلے درست فائل ڈالیں۔ جمع کرانے کے بعد فوراً کوآرڈینیٹر کو بتائیں۔</li>
<li><b>Fail یا Reject ملا:</b> <b>Closed</b> میں نوٹ پڑھیں۔ اگر متفق نہ ہوں تو کوآرڈینیٹر سے بات کریں۔</li>
<li><b>ٹاسک Store میں نظر نہیں آتا:</b> ہو سکتا ہے اس کے لیے ایسی اہلیت چاہیے جو آپ کے پاس نہیں، یا وہ آپ کے اپنے Fail کا دہرایا ہوا ہو۔ اہلیتیں HR تجویز کرتا ہے۔</li>
</ul>
</details>
<p><a class="btn" href="#" data-tab="tasks">Tasks کھولیں</a></p>$help_guide$, 60, true, now(), 'migration 119')
on conflict (slug) do nothing;

insert into public.help_pages (slug, guide_key, language, role, title, summary, section, audience, html_content, sort_order, draft, updated_at, updated_by_email)
values ('talk-team_ur', 'talk-team', 'ur', null, 'ٹیم سے بات کریں', 'اطلاع، شراکت، شمولیت، آپ کی پروفائل', 'work', array['user'], $help_guide$<p class="lead">مختلف باتوں کے لیے مختلف جگہیں ہیں، تاکہ کچھ ضائع نہ ہو۔</p>
<table><tr><th>آپ چاہتے ہیں</th><th>یہاں جائیں</th></tr>
<tr><td>غلطی، نہ کھلنے والی فائل یا تجویز کی اطلاع دینا</td><td><b>Report a Problem or Suggestion</b></td></tr>
<tr><td>کوئی تجربہ، مشکل یا خیال بانٹنا</td><td><b>Share with us</b></td></tr>
<tr><td>آرکائیو پر کام کرنے والی ٹیم میں شامل ہونا</td><td><b>Join the Team</b> (صرف یوزر)</td></tr>
<tr><td>نام، پاس ورڈ یا دوسری معلومات بدلنا</td><td><b>My Profile</b></td></tr></table>
<h2>مسئلے کی اطلاع دیں</h2>
<ol>
<li><b>Report type</b> چنیں اور پیغام لکھیں۔ اگر بات کسی دستاویز کی ہو تو اس کا نمبر لکھیں، یا خود دستاویز پر <b>Report a problem</b> دبائیں۔</li>
<li><b>Send</b> دبائیں۔ کوآرڈینیٹرز اور ایڈمن اسے پڑھتے ہیں اور اسی صفحے پر جواب دیتے ہیں۔ جواب آنے پر آپ کو اطلاع ملتی ہے۔</li>
</ol>
<h2>Share with us</h2>
<p>یہ تکنیکی مسائل کے لیے نہیں۔ یہ اس کے لیے ہے جو آپ جیتے اور سوچتے ہیں، اور ہر شعبے کا سربراہ اسے پڑھتا ہے۔ لکھیں، یا اگر فون اجازت دے تو <b>Record a voice message</b> دبائیں۔ شکریہ اور جواب اسی صفحے پر نظر آتے ہیں۔</p>
<details><summary>Join the Team</summary>
<p>فارم میں اپنا تجربہ، وقت، صلاحیتیں اور مقصد لکھیں اور <b>Submit Request</b> دبائیں۔ HR اسے پڑھتا ہے اور آپ سے رابطہ کر سکتا ہے؛ آخری منظوری ایڈمن دیتا ہے۔ اگر آپ قبول ہو جائیں تو آپریٹر بن جاتے ہیں اور نئے ٹیب نظر آتے ہیں۔</p>
</details>
<details><summary>My Profile</summary>
<ul>
<li><b>Change my password</b> اور <b>Sign out</b>۔</li>
<li><b>My Certificates</b>، تربیتی راستوں سے۔</li>
<li><b>My activity in the archive</b>: جو آپ نے بدلا۔ اسے صرف آپ، ایڈمن اور HR کا سربراہ دیکھ سکتے ہیں۔</li>
</ul>
</details>
<p><a class="btn" href="#" data-tab="profile">My Profile کھولیں</a></p>$help_guide$, 70, true, now(), 'migration 119')
