insert into public.help_pages (slug, guide_key, language, role, title, summary, section, audience, html_content, sort_order, draft, updated_at, updated_by_email)
values ('review-proposals_ur', 'review-proposals', 'ur', null, 'تجاویز کا جائزہ', 'منظور کریں، واپس بھیجیں یا رد کریں', 'check', array['qual:REVISOR', 'coordinator', 'dept:FORM'], $help_guide$<p class="lead">صرف آپ کی منظوری سے تجویز شائع ہو جاتی ہے، اس لیے آرکائیو میں کچھ بھی دوسری نظر کے بغیر نہیں آتا۔ آپ اپنی تجاویز پر فیصلہ نہیں کر سکتے۔</p>
<h2>مراحل</h2>
<ol>
<li><b>قطار کھولیں۔</b> <b>Proposals → To review</b>، سب سے پرانی پہلے۔ آپ کو معلوم نہیں ہوتا کہ تجویز کس کی ہے۔</li>
<li><b>تجویز کھولیں۔</b> پہلے مشترک معلومات، پھر ہر نسخہ اپنے متن، PDF، آڈیو یا ویڈیو کے ساتھ۔</li>
<li><b>اگر وقت چاہیے تو Take it دبائیں۔</b> یہ تجویز ۴۸ گھنٹے آپ کے لیے رکھتا ہے، پھر وہ خود قطار میں لوٹ جاتی ہے۔ <b>Release it</b> اسے پہلے چھوڑ دیتا ہے۔</li>
<li><b>جانچیں۔</b> کیا یہ واقعی نئی ہے یا آرکائیو میں موجود ہے؟ عنوان، مصنف اور تاریخ درست ہیں؟ کلامِ حیات کا اپنا مہینہ ہے؟ رسائی کا درجہ درست ہے؟</li>
<li><b>متن کو اصل سے ملا کر پڑھیں،</b> اگر ہو سکے، اور نشان لگائیں کہ پڑھ لیا۔ تبھی وہ متن دوبارہ پڑھا ہوا مانا جاتا ہے۔ ورنہ وہ غیر تصدیق شدہ رہتا ہے، اور اس کی اجازت ہے۔</li>
<li><b>فیصلہ کریں۔</b></li>
</ol>
<table><tr><th>بٹن</th><th>کب</th><th>کیا ہوتا ہے</th></tr>
<tr><td><b>Approve and publish</b></td><td>درست ہے</td><td>ہر نسخہ اپنے رسائی کے درجے کے مطابق فوراً نظر آتا ہے</td></tr>
<tr><td><b>Send back to correct</b></td><td>ٹھیک ہو سکتی ہے</td><td>تجویز کرنے والا آپ کا نوٹ دیکھتا ہے اور دوبارہ بھیج سکتا ہے</td></tr>
<tr><td><b>Reject</b></td><td>آرکائیو کے لیے نہیں</td><td>تجویز کرنے والا وجہ دیکھتا ہے۔ یہ بند ہو جاتی ہے</td></tr></table>
<details><summary>مخصوص دستاویزات</summary>
<p>مخصوص تجویز کا جائزہ صرف Formation کا کوئی دوسرا رکن یا ایڈمن لے سکتا ہے۔ اگر آپ ان میں سے نہیں تو وہ آپ تک نہیں پہنچتی۔</p>
</details>
<details><summary>تاکہ کچھ رکا نہ رہے</summary>
<p>تجویز کرنے والا ۳ دن بعد یاد دہانی بھیج سکتا ہے، جو قطار تک پہنچتی ہے، کسی ایک شخص تک نہیں۔ ۷ دن بعد تجویز تاخیر والی دکھائی جاتی ہے۔ سب کچھ ایپ کے اندر ہوتا ہے، ای میل کے بغیر، اس لیے قطار باقاعدگی سے دیکھیں۔</p>
</details>
<details><summary>اشاعت کے بعد</summary>
<p>ایڈمن <b>Files for Drive</b> سے PDF کو Drive پر نقل کرتا ہے۔ ایڈمن بعد میں کوئی دستاویز واپس بھی لے سکتا ہے۔ آپ کا ہر عمل ریکارڈ میں رہتا ہے۔</p>
</details>
<p><a class="btn" href="#" data-tab="proposals">Proposals کھولیں</a></p>$help_guide$, 80, true, now(), 'migration 119')
on conflict (slug) do nothing;

