select '27 guides in Urdu' as item,
       (select count(*) = 27 from public.help_pages where language = 'ur') as ok
union all select 'all are still drafts, seen only by Admins',
       (select count(*) = 27 from public.help_pages where language = 'ur' and draft)
union all select 'English and Italian not affected',
       (select count(*) = 54 from public.help_pages where language in ('en', 'it') and not draft)
union all select 'Read aloud guide also for plain Users, as in English',
       (select 'user' = any(audience) from public.help_pages where slug = 'read-aloud_ur');
